      facetA: { ok: "The supersession of the physical newspaper by digital distribution.", d: ["The near-total collapse of the cost of distributing a newspaper.", "The migration of advertising revenue from newsprint to online platforms.", "The preference of younger readers for news delivered by telephone."] },
      mechA: { ok: "collapsing distribution costs to almost nothing while enabling continuous, personalised updating", d: ["displacing print, broadcast and radio alike as the public's primary source of news", "allowing readers to select the subjects and the outlets that already suit them", "permitting publishers to measure precisely which articles attract attention"] },
      exA: { ok: "Established mastheads abandoning weekday print runs for subscription platforms.", d: ["Broadcasters closing their regional television studios in favour of online services.", "Regional titles closing after the loss of classified advertising.", "News aggregators overtaking newspapers as the primary source of headlines."] },
      nuanceA: { ok: "digital migration has severed the revenue model that funded investigative reporting, yielding many platforms and little original journalism", d: ["no printed newspaper anywhere in the world has survived for long once a free and continuously updated digital rival has appeared in its market", "online publication rewards speed and volume, which steadily erodes the verification that serious reporting demands", "readers accustomed to free content have proved markedly reluctant to fund the journalism that they habitually consume"] },
      facetB: { ok: "The enduring civic and material value of the printed edition.", d: ["The enduring appeal of physical books, records and printed matter.", "The tactile pleasure that many readers still take in newsprint.", "The accessibility of print for readers without reliable internet access."] },
      mechB: { ok: "imposing editorial finitude, offering a curated edition that establishes shared civic priorities", d: ["furnishing every reader in the country with an identical account of every single news story of the day", "insulating the reader from the algorithmic sorting that governs digital attention", "sustaining the local advertising market upon which regional reporting still depends"] },
